import requests

sources = frappe.get_all(
	"Threat Source",
	filters={"status": "Approved"},
	fields=["name", "source_name", "source_url", "source_type"],
)

validation_results = {}
for source in sources:
	try:
		response = requests.head(source.source_url, timeout=20, allow_redirects=True)
		validation_results[source.name] = response.status_code < 400
	except Exception:
		validation_results[source.name] = False

result["existing_sources"] = sources
result["validation_results"] = validation_results

from urllib.parse import urlparse

import requests


def _normalize_url(url):
	if not url:
		return ""
	parsed = urlparse(url.lower())
	hostname = parsed.hostname.replace("www.", "") if parsed.hostname else ""
	path = parsed.path.rstrip("/")
	return f"{hostname}{path}"


def _is_url_reachable(url):
	try:
		response = requests.head(url, timeout=5, allow_redirects=True)
		if response.status_code < 400:
			return True
		response = requests.get(url, timeout=5, allow_redirects=True)
		return response.status_code < 400
	except Exception:
		return False


suggestions = (task_data.get("expansion_result") or {}).get("suggestions") or []
reachable = [s for s in suggestions if _is_url_reachable((s.get("url") or "").strip())]

existing_urls_docs = frappe.get_all("Threat Source", fields=["source_url"])
normalized_existing_urls = {
	_normalize_url(d.source_url) for d in existing_urls_docs if d.source_url
}

unique_sources = []
for suggestion in reachable:
	source_url = (suggestion.get("url") or "").strip()
	if not source_url:
		continue
	normalized = _normalize_url(source_url)
	if normalized not in normalized_existing_urls:
		unique_sources.append({
			"source_name": suggestion.get("name"),
			"source_type": suggestion.get("type", "Other"),
			"source_url": source_url,
			"discovery_context": suggestion.get("reason"),
			"language": "English",
		})
		normalized_existing_urls.add(normalized)

result["extracted_sources"] = unique_sources
